# -*- coding: utf-8 -*-
import re, os

base = r'D:\Users\lorns\OneDrive\第二职业\产品经理独孤虾\互联网产品经理自媒体\drafts\2026-08-23\A00级小车销量腰斩-国民神车为何卖不动'

def patch(fname, inserts):
    """inserts: list of (anchor_substring, insert_text) — 在 anchor 之后插入"""
    p = os.path.join(base, fname)
    c = open(p, encoding='utf-8').read()
    for anchor, add in inserts:
        if anchor not in c:
            print(f'  [WARN] anchor not found in {fname}: {anchor[:30]}')
            continue
        c = c.replace(anchor, anchor + '\n\n' + add, 1)
    open(p, 'w', encoding='utf-8').write(c)
    # 统计
    body = c.split('---', 2)[2]
    cut = body.find('## 配图搜索替换指令')
    if cut < 0:
        cut = body.find('[封面图提示词]')
    body = body[:cut]
    lines = [l for l in body.split('\n') if not l.strip().startswith('#')]
    cnt = sum(len(re.findall(r'[\u4e00-\u9fff]', l)) for l in lines)
    print(f'{fname}: {cnt}')

# ============ 知乎版 ============
patch('知乎-国民神车为何卖不动.md', [
    ("# 别喊消费降级了：A00 暴跌、A0 暴涨，消费者的账比你想得清楚\n\n先说结论：A00 级微型车（宏光 MINIEV、海鸥这批 3-5 万的车）上半年销量暴跌 60% 以上，不是消费降级的证据，恰恰是消费升级的证明——消费者不是不买小车了，是不买\"只能代步、不能生活\"的小车了。",
     "这个判断听起来有点反直觉，尤其当舆论正在用\"年轻人不买车\"来归纳一切的时候。但数据摆得很清楚：同样是入门级新能源，A00 同比腰斩的同时 A0 级逆势增长近三成——如果真是\"大家都没钱了\"，为什么 5-8 万的车反而卖爆了？如果真是\"年轻人躺平了\"，为什么同一个月里，吉利星愿能单月卖出 5 万辆？\n\n所以问题的正确问法不是\"市场在萎缩吗\"，而是\"这个品类为什么被抛弃\"。答案指向三个同时发生的结构性变化：政策在退坡、成本在上涨、更高级别的车在降价。三者叠加，A00 赖以生存的\"低价护城河\"被填平，品类退潮就成了必然。本期回答就从这个角度展开。"),
    ("**第三刀：A0 降维打击。** A0 普遍 300-500 公里续航 vs 微型 120-200 公里；标配气囊、倒车影像、快充 vs 微型\"空调算高配\"；空间能坐一家人 vs 后排是摆设。价格只差一万出头。销售的原话：\"看了 MINIEV 再看缤果，很难回得去。\"",
     "特别值得注意的一点是：A0 级能把价格做到 5-8 万，靠的不是压缩安全配置，恰恰相反——它靠的是平台复用和规模效应。A0 车型普遍复用 A 级车的三电和电子架构，电池、电机、底盘都是成熟供应链上的成熟件，一台车的采购成本被摊得极薄；而 A00 级长期使用独立开发的低规格平台，研发和采购都没有规模，成本下不去、配置上不来。同样是\"便宜的小车\"，一个靠规模赢来的便宜，一个靠偷工换来的便宜——退潮一来，高下立判。这也解释了为什么政策撤了、成本涨了之后，A00 完全没有还手之力：它的\"便宜\"从来不是竞争力，只是政策的投影。"),
    ("这让人想起共享单车：资本涌入时满街花花绿绿，退潮后一地鸡毛。中汽协专家说得直白：微型电车的火爆是\"补贴温床\"上长出的畸形繁荣，温床撤走，最先冻死的一定是没有御寒能力的产品。",
     "这里需要澄清一个容易误读的点：我不是说\"所有微型车都该死\"，也不是说\"补贴政策错了\"。购置税减免和购车补贴在新能源产业早期是必要的\"扶上马\"，2023 年多部委发文时就明示了退坡时间表——2026 年减半、2027 年全面恢复，政策设计者本意是等产业有规模了、成本降下来了，再让市场回归真实需求。问题出在品类层面：A00 微型车把\"政策红利\"当成了\"产品力本身\"，三年补贴期里没有完成从\"政策驱动\"到\"产品驱动\"的转身，甚至为了吃补贴不断压低规格、压缩配置。所以政策一停，最先裸泳的必然是它。同类对照：日本的 K-car 之所以能长盛不衰，是因为《轻自动车法》给了它专属的税制、牌照和停车优惠——那是永久性的制度安排，不是一次性的政策红利。中国市场当年没有给微型车类似的\"养育环境\"，却让它承担了比 K-car 更重的期望，这不公平，但这就是现实。"),
    ("从夏利到 QQ 到 MINIEV，每一代\"国民车\"对应一个时代的需求：能开、便宜、代步。今天的需求是\"能开、能用、能生活\"。A00 的退潮是旧定义的退潮，下一根接力棒属于重新定义\"国民小车\"的人。出清不是终点，是下一个品类的起跑线。",
     "往深一层看，这其实是一个\"品类生命周期\"的经典案例：任何品类都有从政策催熟、规模爬坡、到补贴退坡、回归真实需求的阶段。A00 在 2020-2022 年靠补贴完成了启蒙，让数亿普通家庭第一次摸到了方向盘，这个历史功劳不该被抹掉；但它的使命也到此为止。消费者用脚投票的结果非常清晰：不是不要小车，是要一辆\"真正能用\"的小车。对行业而言，A00 的退潮不是利空，恰恰是结构性出清——把资源从\"低价内卷\"里释放出来，流向更有价值的 A0 智能化赛道。对普通消费者来说，这反而是好事：5-8 万价位段正在上演最激烈的配置竞争，你花 7 万左右就能买到带 L2 智驾、500 公里续航、快充的车型——这在三年前是想都不敢想的。"),
])

